180	//手势事件处理函数
181	static void gesture_event_handler(lv_event_t *e)
182	{
183	    lv_event_code_t code = lv_event_get_code(e);
184	    if (code != LV_EVENT_PRESSED && code != LV_EVENT_RELEASED) return;
185	    lv_obj_t *obj = lv_event_get_target(e);
186	    lv_indev_t *indev = lv_event_get_indev(e);
187	    
188	    if (!indev) return;
189	    
190	    lv_point_t point;
191	    lv_indev_get_point(indev, &point);
192	    
193	    switch (code) {
194	        case LV_EVENT_PRESSED:
195	            gesture_start_x = point.x;
196	            gesture_start_y = point.y;
197	            gesture_in_progress = true;
198	            break;
199	        case LV_EVENT_RELEASED:
200	            if (gesture_in_progress) {
201	                int delta_x = point.x - gesture_start_x;
202	                int delta_y = point.y - gesture_start_y;
203	                
204	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
205	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
206	                    // 修改：右滑隐藏秒表界面
207	                    exit_stopwatch();
208	                }
209	                
210	                gesture_in_progress = false;
211	            }
212	            break;
213	        default:
214	            break;
215	    }
216	}
