103	/* ========== 单个应用磁贴 ==========
104	 * 设计稿：圆角矩形卡片，内含彩色圆角图标容器 + 下方文字。
105	 * 4 个应用排成 2×2 网格，整体居中。 */
106	static void create_app_tile(int8_t idx)
107	{
108	    int col = idx % GRID_COLS;
109	    int row = idx / GRID_COLS;
110	    int16_t x = GRID_X0 + col * (TILE_W + TILE_GAP) + TILE_W / 2;
111	    int16_t y = GRID_Y0 + row * (TILE_H + TILE_GAP) + TILE_H / 2;
112	
113	    /* --- 磁贴容器 --- */
114	    ui_tiles[idx] = lv_obj_create(ui_bg);
115	    lv_obj_set_size(ui_tiles[idx], TILE_W, TILE_H);
116	    lv_obj_align(ui_tiles[idx], LV_ALIGN_CENTER, x - SCREEN_W / 2, y - SCREEN_H / 2);
117	    lv_obj_set_style_radius(ui_tiles[idx], TILE_RADIUS, 0);
118	    lv_obj_set_style_bg_color(ui_tiles[idx], BG_CARD, 0);
119	    lv_obj_set_style_bg_opa(ui_tiles[idx], LV_OPA_COVER, 0);
120	    lv_obj_set_style_border_width(ui_tiles[idx], 1, 0);
121	    lv_obj_set_style_border_color(ui_tiles[idx], STROKE_SOFT, 0);
122	    lv_obj_set_style_pad_all(ui_tiles[idx], 0, 0);
123	    lv_obj_clear_flag(ui_tiles[idx], LV_OBJ_FLAG_SCROLLABLE);
124	
125	    /* --- 图标容器（彩色圆角方块）--- */
126	    ui_icon_wraps[idx] = lv_obj_create(ui_tiles[idx]);
127	    lv_obj_set_size(ui_icon_wraps[idx], ICON_SIZE, ICON_SIZE);
128	    lv_obj_align(ui_icon_wraps[idx], LV_ALIGN_TOP_MID, 0, 10);
129	    lv_obj_set_style_radius(ui_icon_wraps[idx], ICON_RADIUS, 0);
130	
131	    /* 半透明背景色：取 icon_bg 的 RGB，alpha 固定 ~18% (LV_OPA_18=46) */
132	    lv_obj_set_style_bg_color(ui_icon_wraps[idx], lv_color_hex(apps[idx].icon_bg), 0);
133	    lv_obj_set_style_bg_opa(ui_icon_wraps[idx], 46, 0);  /* ~18% opacity */
