64	// 创建页面动画
65	static void create_page_animation(lv_obj_t* old_page, lv_obj_t* new_page, 
66	                                 page_animation_t anim_type, bool is_back) {
67	    if (anim_type == PAGE_ANIM_NONE) return;
68	    
69	    lv_anim_t a;
70	    lv_anim_init(&a);
71	    lv_anim_set_time(&a, 300);
72	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
73	    
74	    switch (anim_type) {
75	        case PAGE_ANIM_SLIDE_LEFT:
76	        case PAGE_ANIM_SLIDE_RIGHT:
77	            if (old_page) {
78	                int32_t start_x = 0;
79	                int32_t end_x = is_back ? lv_obj_get_width(old_page) : -lv_obj_get_width(old_page);
80	                if (anim_type == PAGE_ANIM_SLIDE_RIGHT) {
81	                    end_x = -end_x;
82	                }
83	                
84	                lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_x);
85	                lv_anim_set_var(&a, old_page);
86	                lv_anim_set_values(&a, start_x, end_x);
87	                lv_anim_start(&a);
88	            }
89	            
90	            if (new_page) {
91	                int32_t start_x = is_back ? -lv_obj_get_width(new_page) : lv_obj_get_width(new_page);
92	                int32_t end_x = 0;
93	                if (anim_type == PAGE_ANIM_SLIDE_RIGHT) {
94	                    start_x = -start_x;
95	                }
96	                
97	                lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_x);
98	                lv_anim_set_var(&a, new_page);
99	                lv_anim_set_values(&a, start_x, end_x);
100	                lv_anim_start(&a);
101	            }
102	            break;
103	            
104	        case PAGE_ANIM_FADE:
105	            if (old_page) {
106	                lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_style_opa);
107	                lv_anim_set_var(&a, old_page);
108	                lv_anim_set_values(&a, LV_OPA_COVER, LV_OPA_TRANSP);
109	                lv_anim_start(&a);
110	            }
111	            
112	            if (new_page) {
113	                lv_obj_set_style_opa(new_page, LV_OPA_TRANSP, 0);
114	                lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_style_opa);
115	                lv_anim_set_var(&a, new_page);
116	                lv_anim_set_values(&a, LV_OPA_TRANSP, LV_OPA_COVER);
117	                lv_anim_start(&a);
118	            }
119	            break;
120	            
121	        default:
122	            break;
123	    }
124	}
