126	// 添加到历史记录
127	static bool add_to_history(uint32_t app_id, uint32_t page_id) {
128	    if (!nav_mgr.history_head && app_id == nav_mgr.home_app_id && 
129	        page_id == nav_mgr.home_page_id) {
130	        // 主页不添加到历史记录
131	        return true;
132	    }
133	    
134	    if (nav_mgr.history_count >= MAX_HISTORY) {
135	        // 移除最旧的记录
136	        page_history_node_t* old_head = nav_mgr.history_head;
137	        nav_mgr.history_head = old_head->next;
138	        if (nav_mgr.history_head) {
139	            nav_mgr.history_head->prev = NULL;
140	        }
141	        free(old_head);
142	        nav_mgr.history_count--;
143	    }
144	    
145	    page_history_node_t* new_node = malloc(sizeof(page_history_node_t));
146	    if (!new_node) return false;
147	    
148	    new_node->app_id = app_id;
149	    new_node->page_id = page_id;
150	    new_node->next = NULL;
151	    new_node->prev = nav_mgr.history_tail;
152	    
153	    if (nav_mgr.history_tail) {
154	        nav_mgr.history_tail->next = new_node;
155	    }
156	    nav_mgr.history_tail = new_node;
157	    
158	    if (!nav_mgr.history_head) {
159	        nav_mgr.history_head = new_node;
160	    }
161	    
162	    nav_mgr.history_count++;
163	    return true;
164	}
