166	// 从历史记录移除
167	static void remove_from_history(void) {
168	    if (!nav_mgr.history_tail) return;
169	    
170	    page_history_node_t* tail = nav_mgr.history_tail;
171	    nav_mgr.history_tail = tail->prev;
172	    
173	    if (nav_mgr.history_tail) {
174	        nav_mgr.history_tail->next = NULL;
175	    } else {
176	        nav_mgr.history_head = NULL;
177	    }
178	    
179	    free(tail);
180	    nav_mgr.history_count--;
181	}
