197	// 显示目标页面
198	static bool show_target_page(nav_page_t* target_page) {
199	    if (!target_page) return false;
200	    
201	    // 加载页面（如果未加载）
202	    if (target_page->state == PAGE_STATE_UNLOADED) {
203	        if (target_page->on_create) {
204	            target_page->page_obj = target_page->on_create();
205	            if (target_page->page_obj) {
206	                lv_obj_set_parent(target_page->page_obj, nav_mgr.container);
207	                lv_obj_set_size(target_page->page_obj, LV_PCT(100), LV_PCT(100));
208	                lv_obj_add_flag(target_page->page_obj, LV_OBJ_FLAG_HIDDEN);
209	            } else {
210	                return false;
211	            }
212	        } else {
213	            return false;
214	        }
215	    }
216	    
217	    // 显示页面
218	    if (target_page->page_obj) {
219	        lv_obj_clear_flag(target_page->page_obj, LV_OBJ_FLAG_HIDDEN);
220	        lv_obj_move_foreground(target_page->page_obj);
221	        
222	        target_page->state = PAGE_STATE_ACTIVE;
223	        
224	        // 更新应用加载状态
225	        if (target_page->app) {
226	            target_page->app->is_loaded = true;
227	        }
228	        
229	        // 触发恢复回调
230	        if (target_page->on_resume) {
231	            target_page->on_resume(target_page->page_obj);
232	        }
233	        
234	        return true;
235	    }
236	    
237	    return false;
238	}
