260	bool nav_register_app(nav_app_t* app) {
261	    if (!nav_mgr.initialized || !app || nav_mgr.app_count >= MAX_APPS) {
262	        return false;
263	    }
264	    
265	    // 检查是否已注册
266	    if (find_app(app->id)) {
267	        return false;
268	    }
269	    
270	    // 添加到应用链表头部
271	    app->next = nav_mgr.app_list;
272	    nav_mgr.app_list = app;
273	    app->is_loaded = false;
274	    app->first_page = NULL;
275	    
276	    nav_mgr.app_count++;
277	    return true;
278	}
