280	bool nav_register_page(nav_page_t* page) {
281	    if (!nav_mgr.initialized || !page || nav_mgr.page_count >= MAX_PAGES) {
282	        return false;
283	    }
284	    
285	    // 检查是否已注册
286	    if (find_page(page->app_id, page->page_id)) {
287	        return false;
288	    }
289	    
290	    // 查找所属应用
291	    nav_app_t* app = find_app(page->app_id);
292	    if (!app) {
293	        // 应用未注册，自动创建默认应用
294	        static nav_app_t default_app = {0};
295	        default_app.id = page->app_id;
296	        default_app.package_name = "default.app";
297	        default_app.icon_url = "";
298	        default_app.get_name = NULL;
299	        
300	        if (!nav_register_app(&default_app)) {
301	            return false;
302	        }
303	        app = &default_app;
304	    }
305	    
306	    // 设置应用关联
307	    page->app = app;
308	    
309	    // 如果是应用的第一个页面，设置应用的首页面
310	    if (!app->first_page) {
311	        app->first_page = page;
312	    }
313	    
314	    // 添加到页面链表头部
315	    page->next = nav_mgr.page_list;
316	    nav_mgr.page_list = page;
317	    
318	    // 初始化页面状态
319	    page->state = PAGE_STATE_UNLOADED;
320	    page->page_obj = NULL;
321	    page->user_data = NULL;
322	    
323	    nav_mgr.page_count++;
324	    return true;
325	}
