327	bool nav_switch_to_page(uint32_t app_id, uint32_t page_id, page_animation_t anim_type) {
328	    if (!nav_mgr.initialized) return false;
329	    
330	    nav_page_t* target_page = find_page(app_id, page_id);
331	    if (!target_page) return false;
332	    
333	    nav_page_t* current_page = nav_mgr.current_page;
334	    
335	    // 隐藏当前页面
336	    hide_current_page();
337	    
338	    // 显示目标页面
339	    if (!show_target_page(target_page)) {
340	        return false;
341	    }
342	    
343	    // 添加到历史记录
344	    if (current_page && (current_page->app_id != app_id || current_page->page_id != page_id)) {
345	        add_to_history(current_page->app_id, current_page->page_id);
346	    }
347	    
348	    nav_mgr.current_page = target_page;
349	    
350	    // 执行动画
351	    create_page_animation(current_page ? current_page->page_obj : NULL,
352	                         target_page->page_obj,
353	                         anim_type != PAGE_ANIM_NONE ? anim_type : nav_mgr.default_anim,
354	                         false);
355	    
356	    return true;
357	}
