383	bool nav_destroy_page(uint32_t app_id, uint32_t page_id) {
384	    nav_page_t* page = find_page(app_id, page_id);
385	    if (!page || !page->page_obj) return false;
386	    
387	    // 如果正在显示该页面，先切换页面
388	    if (nav_mgr.current_page == page) {
389	        if (nav_mgr.history_tail) {
390	            nav_go_back(PAGE_ANIM_NONE);
391	        } else {
392	            // 没有历史记录，隐藏当前页面
393	            hide_current_page();
394	            nav_mgr.current_page = NULL;
395	        }
396	    }
397	    
398	    // 调用销毁回调
399	    if (page->on_destroy) {
400	        page->on_destroy(page->page_obj);
401	    } else {
402	        lv_obj_del(page->page_obj);
403	    }
404	    
405	    page->page_obj = NULL;
406	    page->state = PAGE_STATE_UNLOADED;
407	    page->user_data = NULL;
408	    
409	    return true;
410	}
