412	bool nav_destroy_app(uint32_t app_id) {
413	    nav_app_t* app = find_app(app_id);
414	    if (!app) return false;
415	    
416	    bool success = true;
417	    nav_page_t* page = nav_mgr.page_list;
418	    
419	    // 销毁该应用的所有页面
420	    while (page) {
421	        if (page->app_id == app_id) {
422	            if (!nav_destroy_page(app_id, page->page_id)) {
423	                success = false;
424	            }
425	        }
426	        page = page->next;
427	    }
428	    
429	    app->is_loaded = false;
430	    return success;
431	}
