59	/* 恢复表盘：取消 HIDDEN。timer 一直在走，秒针角度已是当前值，直接显示无跳动。 */
60	static void watch_show(void)
61	{
62	    if (mpd && mpd->mainPage) {
63	        lv_obj_clear_flag(mpd->mainPage, LV_OBJ_FLAG_HIDDEN);
64	    }
65	}
