67	/* 从二级页返回 home 时恢复表盘可见性（表盘对象树始终未删除）。 */
68	static void watch_show_home(void)
69	{
70	    if (mpd && mpd->mainPage) {
71	        lv_obj_clear_flag(mpd->mainPage, LV_OBJ_FLAG_HIDDEN);
72	    }
73	}
