75	/* 二级应用页退出后回调：按 g_prev_page 重建上层。
76	 * 暴露给各二级页（stopwatch/calendar/...）的退出函数末尾调用。 */
77	void nav_return_from_app(void)
78	{
79	    if (g_prev_page == PAGE_APPLIST) {
80	        /* 二级页返回列表：建好列表即可（表盘此时仍 hidden，列表盖满；无滑入动画免卡顿） */
81	        mpd->appListCenter = lv_obj_create(mpd->watchScr);
82	        applist_create_list(mpd->appListCenter);
83	        g_current_page = PAGE_APPLIST;
84	        strcpy(mpd->current_page, APPS_PAGE);
85	    } else {
86	        watch_show_home();
87	        g_current_page = PAGE_HOME;
88	        strcpy(mpd->current_page, HOME_PAGE);
89	    }
90	}
