92	/* 进入二级应用页前回调：隐藏列表（不删除，避免 TLSF 堆损坏），记栈上层=列表。
93	 * 供 list.c 的 app_click_event_cb 在调用 xxx_start() 前调用。
94	 *
95	 * CRITICAL: Do NOT call lv_obj_delete/lv_obj_del here. On BES1700,
96	 * lv_obj_del corrupts the TLSF heap, causing必现 MMFAR=0x15c crash
97	 * when LVGL later allocates memory during rendering. Instead, hide the
98	 * object with LV_OBJ_FLAG_HIDDEN. */
99	void nav_enter_app(void)
100	{
101	    if (mpd->appListCenter != NULL) {
102	        lv_anim_delete(mpd->appListCenter, anim_translate_y_cb);
103	        applist_hide_page();
104	        lv_obj_delete(mpd->appListCenter);
105	        mpd->appListCenter = NULL;
106	    }
107	    g_prev_page = PAGE_APPLIST;
108	    g_current_page = PAGE_APP;
109	    strcpy(mpd->current_page, INSOMEONEAPP_PAGE);
110	}
