274	static void watch_sys_gesture_event_cb(lv_event_t *e)
275	{
276	    lv_event_code_t code = lv_event_get_code(e);
277	    lv_indev_t *indev = lv_indev_active();
278	    if (!indev) return;
279	
280	    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
281	
282	    switch (code)
283	    {
284	    case LV_EVENT_GESTURE:
285	        if (dir == LV_DIR_LEFT)
286	        {
287	            if (!strcmp(mpd->current_page, HOME_PAGE))
288	            {
289	                g_prev_page = PAGE_HOME;
290	
291	                /* 先建好列表（ui_bg 实色盖满整屏），再隐藏表盘——
292	                 * 顺序不能反：先 hide 会露出黑底直到列表盖上来（黑屏）；
293	                 * 列表已就位盖满后再 hide 表盘只是省绘制，用户无感知，且无两层渲染卡顿。 */
294	                mpd->appListCenter = lv_obj_create(mpd->watchScr);
295	                app_launcher_create(mpd->appListCenter);
296	                watch_hide();
297	                g_current_page = PAGE_APPLIST;
298	                strcpy(mpd->current_page, APPS_PAGE);
299	            }
300	            else
301	            {
302	                bool is_home_page = !strcmp(mpd->current_page, HOME_PAGE);
303	                LV_LOG_USER("LV_DIR_LEFT + currentPage: %s, is_home_page %d \n", mpd->current_page, is_home_page);
304	            }
305	        }
306	        if (dir == LV_DIR_RIGHT)
307	        {
308	            LV_LOG_USER("LV_DIR_RIGHT  currentPage: %s \n", mpd->current_page);
