704	 * Connecting动画函数 - 轨道圆环
705	 ****************************************************************************/
706	
707	/* 轨道动画参数 */
708	#define ORBIT_INNER_SIZE    180     /* 内圈直径 */
709	#define ORBIT_OUTER_SIZE    230     /* 外圈直径 */
710	#define ORBIT_ANIM_MS       80      /* 动画刷新间隔(12.5fps，避免闪烁) */
711	
712	/* 轨道动画状态 */
713	static lv_obj_t *s_orbit_container = NULL;   /* 轨道容器 */
714	static lv_obj_t *s_orbit_inner = NULL;       /* 内圈 */
715	static lv_obj_t *s_orbit_outer = NULL;       /* 外圈 */
716	static lv_timer_t *s_orbit_timer = NULL;
717	static int s_orbit_tick = 0;
718	
719	/* 定时器回调：更新轨道旋转 */
720	static void orbit_tick_cb(lv_timer_t *t)
721	{
722	    (void)t;
723	
724	    s_orbit_tick++;
725	
726	    /* 内圈旋转 ~2.25s/圈, 每次转13度 (80ms间隔) */
727	    if (s_orbit_inner != NULL)
728	    {
729	        int32_t angle = (s_orbit_tick * 13) % 360;
730	        lv_arc_set_rotation(s_orbit_inner, angle);
731	    }
732	
733	    /* 外圈反向旋转 ~3s/圈, 每次转10度 */
734	    if (s_orbit_outer != NULL)
735	    {
736	        int32_t angle = 360 - ((s_orbit_tick * 10) % 360);
737	        lv_arc_set_rotation(s_orbit_outer, angle);
738	    }
739	}
740	
741	/* 前向声明 */
742	void ripple_anim_stop(void);
743	void playing_anim_stop(void);
744	
745	/* 启动Connecting动画 - 轨道弧形条 */
746	void connecting_anim_start(lv_obj_t *parent)
747	{
748	    /* 如果已经创建，先停止 */
749	    connecting_anim_stop();
750	
751	    s_orbit_tick = 0;
752	
753	    /* 创建轨道容器 */
754	    s_orbit_container = lv_obj_create(parent);
755	    if (s_orbit_container == NULL) {
756	        printf("[xiaozhi] connecting_anim_start: failed to create container\n");
757	        return;
758	    }
759	    lv_obj_set_size(s_orbit_container, ORBIT_OUTER_SIZE + 10, ORBIT_OUTER_SIZE + 10);
760	    lv_obj_align(s_orbit_container, LV_ALIGN_CENTER, 0, -85);  /* 与按钮重叠 */
761	    lv_obj_set_style_bg_opa(s_orbit_container, LV_OPA_TRANSP, 0);
762	    lv_obj_set_style_border_width(s_orbit_container, 0, 0);
763	    lv_obj_set_style_pad_all(s_orbit_container, 0, 0);
764	    lv_obj_clear_flag(s_orbit_container, LV_OBJ_FLAG_SCROLLABLE);
765	    lv_obj_remove_flag(s_orbit_container, LV_OBJ_FLAG_CLICKABLE);
766	
767	    /* 内圈弧 - 90度弧形（1/4圆），橙色 */
768	    s_orbit_inner = lv_arc_create(s_orbit_container);
769	    lv_obj_set_size(s_orbit_inner, ORBIT_INNER_SIZE, ORBIT_INNER_SIZE);
770	    lv_obj_align(s_orbit_inner, LV_ALIGN_CENTER, 0, 0);
771	    lv_arc_set_bg_angles(s_orbit_inner, 0, 360);       /* 背景完整圆 */
772	    lv_arc_set_angles(s_orbit_inner, 0, 90);           /* 显示90度弧(1/4圆) */
773	    lv_arc_set_value(s_orbit_inner, 25);
774	    /* 隐藏arc对象自身的背景圆 */
775	    lv_obj_set_style_bg_opa(s_orbit_inner, LV_OPA_TRANSP, 0);
776	    /* 背景轨道：淡橙色 */
777	    lv_obj_set_style_arc_width(s_orbit_inner, 2, LV_PART_MAIN);
778	    lv_obj_set_style_arc_color(s_orbit_inner, lv_color_hex(0xFFE0B2), LV_PART_MAIN);
779	    lv_obj_set_style_arc_opa(s_orbit_inner, LV_OPA_60, LV_PART_MAIN);
780	    /* 指示器：深橙色 */
781	    lv_obj_set_style_arc_width(s_orbit_inner, 2, LV_PART_INDICATOR);
782	    lv_obj_set_style_arc_color(s_orbit_inner, lv_color_hex(0xE08A00), LV_PART_INDICATOR);
783	    lv_obj_set_style_arc_opa(s_orbit_inner, LV_OPA_COVER, LV_PART_INDICATOR);
784	    /* 隐藏指示器端点圆球 */
785	    lv_obj_set_style_arc_rounded(s_orbit_inner, false, LV_PART_INDICATOR);
786	    /* 移除knob（主题默认蓝色圆点） */
787	    lv_obj_remove_style(s_orbit_inner, NULL, LV_PART_KNOB);
788	    lv_obj_remove_flag(s_orbit_inner, LV_OBJ_FLAG_CLICKABLE);
789	
790	    /* 外圈弧 - 90度弧形，反向旋转 */
791	    s_orbit_outer = lv_arc_create(s_orbit_container);
792	    lv_obj_set_size(s_orbit_outer, ORBIT_OUTER_SIZE, ORBIT_OUTER_SIZE);
793	    lv_obj_align(s_orbit_outer, LV_ALIGN_CENTER, 0, 0);
794	    lv_arc_set_bg_angles(s_orbit_outer, 0, 360);       /* 背景完整圆 */
795	    lv_arc_set_angles(s_orbit_outer, 0, 90);           /* 显示90度弧 */
796	    lv_arc_set_value(s_orbit_outer, 25);
