119	static void conv_touch_sample(lv_indev_t * drv,
120	                              lv_indev_data_t * data,
121	                              struct touch_sample_s * sample)
122	{
123	    lv_nuttx_touchscreen_t * touchscreen = drv->driver_data;
124	    uint8_t touch_flags = sample->point[0].flags;
125	
126	    if(touch_flags & (TOUCH_DOWN | TOUCH_MOVE)) {
127	        lv_display_t * disp = lv_indev_get_display(drv);
128	        int32_t hor_max = lv_display_get_horizontal_resolution(disp) - 1;
129	        int32_t ver_max = lv_display_get_vertical_resolution(disp) - 1;
130	
131	        data->point.x = LV_CLAMP(0, sample->point[0].x, hor_max);
132	        data->point.y = LV_CLAMP(0, sample->point[0].y, ver_max);
133	        touchscreen->last_state = LV_INDEV_STATE_PRESSED;
134	    }
135	    else if(touch_flags & TOUCH_UP) {
136	        touchscreen->last_state = LV_INDEV_STATE_RELEASED;
137	    }
138	}
139	
140	static bool touchscreen_read_sample(int fd, struct touch_sample_s * sample)
141	{
142	    int nbytes = read(fd, sample, sizeof(struct touch_sample_s));
143	    return nbytes == sizeof(struct touch_sample_s);
144	}
145	
146	static void touchscreen_read(lv_indev_t * drv, lv_indev_data_t * data)
147	{
148	    lv_nuttx_touchscreen_t * touchscreen = drv->driver_data;
149	    struct touch_sample_s sample;
150	
151	    /* Note: Since it is necessary to avoid multi-processing click events
152	    * caused by redundant continue_reading, a two-unit sample sliding window
153	    * algorithm is used here. continue_reading is only activated when there
154	    * are two points in the window.
155	    */
156	
157	    /* If has last sample, use it first */
158	    if(touchscreen->has_last_sample) {
159	        conv_touch_sample(drv, data, &touchscreen->last_sample);
160	    }
161	    else {
162	        /* Read first sample */
163	        if(!touchscreen_read_sample(touchscreen->fd, &sample)) {
164	            /* No sample available, return last state */
165	            data->state = touchscreen->last_state;
166	            return;
167	        }
168	
169	        conv_touch_sample(drv, data, &sample);
170	    }
171	
172	    /* Try to read next sample */
173	    if(touchscreen_read_sample(touchscreen->fd, &sample)) {
174	        /* Save last sample and let lvgl continue reading */
175	        touchscreen->last_sample = sample;
176	        touchscreen->has_last_sample = true;
177	        data->continue_reading = true;
178	    }
179	    else {
180	        /* No more sample available, clear last sample flag */
181	        touchscreen->has_last_sample = false;
182	    }
183	
184	    data->state = touchscreen->last_state;
185	}
