187	static void touchscreen_delete_cb(lv_event_t * e)
188	{
189	    lv_indev_t * indev = (lv_indev_t *) lv_event_get_user_data(e);
190	    lv_nuttx_touchscreen_t * touchscreen = lv_indev_get_driver_data(indev);
191	    if(touchscreen) {
192	        lv_indev_set_driver_data(indev, NULL);
193	        lv_indev_set_read_cb(indev, NULL);
194	        indev_set_cursor(indev, -1);
195	        if(touchscreen->fd >= 0) {
196	            close(touchscreen->fd);
197	            touchscreen->fd = -1;
198	        }
199	        lv_free(touchscreen);
200	        LV_LOG_USER("done");
201	    }
202	}
203	
204	static lv_indev_t * touchscreen_init(int fd)
205	{
206	    lv_nuttx_touchscreen_t * touchscreen;
207	    lv_indev_t * indev = NULL;
208	
209	    touchscreen = lv_malloc_zeroed(sizeof(lv_nuttx_touchscreen_t));
210	    if(touchscreen == NULL) {
211	        LV_LOG_ERROR("touchscreen_s malloc failed");
212	        return NULL;
213	    }
214	
215	    touchscreen->fd = fd;
216	    touchscreen->last_state = LV_INDEV_STATE_RELEASED;
217	    touchscreen->indev_drv = indev = lv_indev_create();
218	
219	    lv_indev_set_type(indev, LV_INDEV_TYPE_POINTER);
220	    lv_indev_set_read_cb(indev, touchscreen_read);
221	    lv_indev_set_driver_data(indev, touchscreen);
222	    lv_indev_add_event_cb(indev, touchscreen_delete_cb, LV_EVENT_DELETE, indev);
223	    return indev;
224	}
