/* 电源按键异步回调：在 LVGL 线程中打开 xiaozhi_voice */
static void power_btn_async_cb(void *arg)
{
    (void)arg;
    if (mpd && !strcmp(mpd->current_page, HOME_PAGE)) {
        LV_LOG_USER("Power button: opening xiaozhi_voice");
        nav_enter_app();
        xiaozhi_voice_start();
    }
