/* 电源按键监听线程：从 /dev/kbd0 读取键盘事件，检测 KEY_POWER */
static void *power_btn_thread(void *arg)
{
    (void)arg;
    int fd = open("/dev/kbd0", O_RDONLY | O_NONBLOCK);
    if (fd < 0) {
        printf("[watch_start] Failed to open /dev/kbd0: not available\n");
        return NULL;
    }

    printf("[watch_start] Power button listener started on /dev/kbd0\n");

    struct keyboard_event_s evt;
    while (1) {
        ssize_t n = read(fd, &evt, sizeof(evt));
        if (n == sizeof(evt)) {
            /* evt.code 是键盘码，evt.type == 1 表示按下 */
            if (evt.code == KEY_POWER && evt.type == 1) {
                printf("[watch_start] KEY_POWER pressed!\n");
                /* 在 LVGL 线程中异步执行，避免线程安全问题 */
                lv_async_call(power_btn_async_cb, NULL);
            }
        } else {
            /* 无事件时休眠，避免忙等 */
            usleep(50 * 1000);  /* 50ms */
        }
    }

    close(fd);
    return NULL;
}

