152	/****************************************************************************
153	 * Name: btn_enable
154	 ****************************************************************************/
155	
156	static void btn_enable(FAR struct btn_upperhalf_s *priv)
157	{
158	  FAR const struct btn_lowerhalf_s *lower;
159	  FAR struct btn_open_s *opriv;
160	  btn_buttonset_t press;
161	  btn_buttonset_t release;
162	  irqstate_t flags;
163	
164	  DEBUGASSERT(priv && priv->bu_lower);
165	  lower = priv->bu_lower;
166	
167	  /* This routine is called both task level and interrupt level, so
168	   * interrupts must be disabled.
169	   */
170	
171	  flags = enter_critical_section();
172	
173	  /* Visit each opened reference to the device */
174	
175	  press   = 0;
176	  release = 0;
177	
178	  for (opriv = priv->bu_open; opriv; opriv = opriv->bo_flink)
179	    {
180	      /* OR in the poll event buttons */
181	
182	      press   |= opriv->bo_pollevents.bp_press;
183	      release |= opriv->bo_pollevents.bp_release;
184	
185	      /* OR in the signal events */
186	
187	      press   |= opriv->bo_notify.bn_press;
188	      release |= opriv->bo_notify.bn_release;
189	    }
190	
191	  /* Enable/disable button interrupts */
192	
193	  DEBUGASSERT(lower->bl_enable);
194	  if (press != 0 || release != 0)
195	    {
196	      /* Update last sampled button states when enabling interrupts for
197	       * the first time.
198	       */
199

200	      if (!priv->bu_enabled)
201	        {
202	          priv->bu_enabled = true;
203	          priv->bu_sample = lower->bl_buttons(lower);
204	        }
205	
206	      /* Enable interrupts with the new button set */
207	
208	      lower->bl_enable(lower, press, release,
209	                       (btn_handler_t)btn_interrupt, priv);
210	    }
211	  else
212	    {
213	      priv->bu_enabled = false;
214	
215	      /* Disable further interrupts */
216	
217	      lower->bl_enable(lower, 0, 0, NULL, NULL);
218	    }
219	
220	  leave_critical_section(flags);
221	}
