223	/****************************************************************************
224	 * Name: btn_interrupt
225	 ****************************************************************************/
226	
227	static void btn_interrupt(FAR const struct btn_lowerhalf_s *lower,
228	                          FAR void *arg)
229	{
230	  FAR struct btn_upperhalf_s *priv = (FAR struct btn_upperhalf_s *)arg;
231	
232	  DEBUGASSERT(priv);
233	
234	  /* Process the next sample */
235	
236	#if CONFIG_INPUT_BUTTONS_DEBOUNCE_DELAY
237	  wd_start(&priv->bu_wdog, MSEC2TICK(CONFIG_INPUT_BUTTONS_DEBOUNCE_DELAY),
238	           btn_sample, (wdparm_t)priv);
239	#else
240	  btn_sample((wdparm_t)priv);
241	#endif
242	}
243	
244	/****************************************************************************
245	 * Name: btn_sample
246	 ****************************************************************************/
247	
248	static void btn_sample(wdparm_t arg)
249	{
250	  FAR struct btn_upperhalf_s *priv;
251	  FAR const struct btn_lowerhalf_s *lower;
252	  FAR struct btn_open_s *opriv;
253	  btn_buttonset_t sample;
254	  btn_buttonset_t change;
255	  btn_buttonset_t press;
256	  btn_buttonset_t release;
257	
258	  priv = (FAR struct btn_upperhalf_s *)arg;
259	  DEBUGASSERT(priv && priv->bu_lower);
260	  lower = priv->bu_lower;
261	
262	  /* Sample the new button state */
263	
264	  DEBUGASSERT(lower->bl_buttons);
265	  sample = lower->bl_buttons(lower);
266	
267	  add_ui_randomness(sample);
268	
269	  /* Determine which buttons have been newly pressed and which have been
270	   * newly released.
271	   */
272	
273	  change = sample ^ priv->bu_sample;
274	  press  = change & sample;
275	
276	  DEBUGASSERT(lower->bl_supported);
277	  release = change & (lower->bl_supported(lower) & ~sample);
278	
279	  /* Visit each opened reference to the device */
280	
281	  for (opriv = priv->bu_open; opriv; opriv = opriv->bo_flink)
282	    {
283	      /* Always set bo_pending true, only clear it after button read */
284	
285	      opriv->bo_pending = true;
286	
287	      /* Have any poll events occurred? */
288	
289	      if ((press & opriv->bo_pollevents.bp_press)     != 0 ||
290	          (release & opriv->bo_pollevents.bp_release) != 0)
291	        {
292	          /* Yes.. Notify all waiters */
293	
294	          poll_notify(opriv->bo_fds, CONFIG_INPUT_BUTTONS_NPOLLWAITERS,
295	                      POLLIN);
296	        }
297	
298	      /* Have any signal events occurred? */
299

300	      if ((press & opriv->bo_notify.bn_press)     != 0 ||
301	          (release & opriv->bo_notify.bn_release) != 0)
302	        {
303	          /* Yes.. Signal the waiter */
304	
305	          opriv->bo_notify.bn_event.sigev_value.sival_int = sample;
306	          nxsig_notification(opriv->bo_pid, &opriv->bo_notify.bn_event,
307	                             SI_QUEUE, &opriv->bo_work);
308	        }
309	    }
310	
311	  priv->bu_sample = sample;
312	}
