317	
318	static int btn_open(FAR struct file *filep)
319	{
320	  FAR struct inode *inode;
321	  FAR struct btn_upperhalf_s *priv;
322	  FAR struct btn_open_s *opriv;
323	  FAR const struct btn_lowerhalf_s *lower;
324	  btn_buttonset_t supported;
325	  irqstate_t flags;
326	
327	  inode = filep->f_inode;
328	  DEBUGASSERT(inode->i_private);
329	  priv = inode->i_private;
330	
331	  /* Allocate a new open structure */
332	
333	  opriv = kmm_zalloc(sizeof(struct btn_open_s));
334	  if (!opriv)
335	    {
336	      ierr("ERROR: Failed to allocate open structure\n");
337	      return -ENOMEM;
338	    }
339	
340	  /* Initialize the open structure */
341	
342	  lower = priv->bu_lower;
343	  DEBUGASSERT(lower && lower->bl_supported);
344	
345	  flags = enter_critical_section();
346	
347	  supported = lower->bl_supported(lower);
348	  opriv->bo_pollevents.bp_press   = supported;
349	  opriv->bo_pollevents.bp_release = supported;
350	  opriv->bo_pending = true;
351	
352	  /* Attach the open structure to the device */
353	
354	  opriv->bo_flink = priv->bu_open;
355	  priv->bu_open = opriv;
356	
357	  /* Attach the open structure to the file structure */
358	
359	  filep->f_priv = (FAR void *)opriv;
360	
361	  /* Enable/disable interrupt handling */
362	
363	  btn_enable(priv);
364	
365	  leave_critical_section(flags);
366	  return OK;
367	}
