532	/****************************************************************************
533	 * Name: btn_ioctl
534	 ****************************************************************************/
535	
536	static int btn_ioctl(FAR struct file *filep, int cmd, unsigned long arg)
537	{
538	  FAR struct inode *inode;
539	  FAR struct btn_upperhalf_s *priv;
540	  FAR struct btn_open_s *opriv;
541	  FAR const struct btn_lowerhalf_s *lower;
542	  irqstate_t flags;
543	  int ret = OK;
544	
545	  DEBUGASSERT(filep->f_priv);
546	  opriv = filep->f_priv;
547	  inode = filep->f_inode;
548	  DEBUGASSERT(inode->i_private);
549	  priv  = inode->i_private;
550	
551	  /* Get exclusive access to the driver structure */
552	
553	  flags = enter_critical_section();
554	
555	  /* Handle the ioctl command */
556	
557	  ret = -EINVAL;
558	  switch (cmd)
559	    {
560	    /* Command:     BTNIOC_SUPPORTED
561	     * Description: Report the set of button events supported by the
562	     *              hardware;
563	     * Argument:    A pointer to writeable integer value in which to return
564	     *              the set of supported buttons.
565	     * Return:      Zero (OK) on success.  Minus one will be returned on
566	     *              failure with the errno value set appropriately.
567	     */
568	
