181	//手势事件处理函数
182	static void gesture_event_handler(lv_event_t *e)
183	{
184	    lv_event_code_t code = lv_event_get_code(e);
185	    if (code != LV_EVENT_PRESSED && code != LV_EVENT_RELEASED) return;
186	    lv_obj_t *obj = lv_event_get_target(e);
187	    lv_indev_t *indev = lv_event_get_indev(e);
188	    
189	    if (!indev) return;
190	    
191	    lv_point_t point;
192	    lv_indev_get_point(indev, &point);
193	    
194	    switch (code) {
195	        case LV_EVENT_PRESSED:
196	            gesture_start_x = point.x;
197	            gesture_start_y = point.y;
198	            gesture_in_progress = true;
199	            break;
200	        case LV_EVENT_RELEASED:
201	            if (gesture_in_progress) {
202	                int delta_x = point.x - gesture_start_x;
203	                int delta_y = point.y - gesture_start_y;
204	                
205	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
206	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
207	                    // 修改：右滑隐藏秒表界面
208	                    exit_stopwatch();
209	                }
210	                
211	                gesture_in_progress = false;
212	            }
213	            break;
214	        default:
215	            break;
216	    }
217	}
