219	static void stopwatch_gesture_event_cb(lv_event_t *e)
220	{
221	    lv_obj_t * obj = lv_event_get_user_data(e);
222	    lv_event_code_t code = lv_event_get_code(e);
223	
224	    switch (code)
225	    {
226	    case LV_EVENT_GESTURE:
227	        lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
228	        if (dir == LV_DIR_BOTTOM)
229	        {
230	            LV_LOG_USER(" LOG_DIR_BOTTOM---But do nothing\n");
231	        }
232	        if (dir == LV_DIR_TOP)
233	        {
234	            LV_LOG_USER(" LV_DIR_TOP---But do nothing\n");
235	        }
236	        if (dir == LV_DIR_LEFT)
237	        {
238	            LV_LOG_USER(" LV_DIR_LEFT---But do nothing\n");
239	        }
240	        if (dir == LV_DIR_RIGHT)
241	        {
242	            LV_LOG_USER(" LV_DIR_RIGHT---Exit\n");
243	            exit_stopwatch();
244	            break;
245	        }
246	
247	    default:
248	        break;
249	    }
250	}
