185	//手势事件处理函数
186	static void gesture_event_handler(lv_event_t *e)
187	{
188	    lv_event_code_t code = lv_event_get_code(e);
189	    if (code != LV_EVENT_PRESSED && code != LV_EVENT_RELEASED) return;
190	    lv_obj_t *obj = lv_event_get_target(e);
191	    lv_indev_t *indev = lv_event_get_indev(e);
192	    
193	    if (!indev) return;
194	    
195	    lv_point_t point;
196	    lv_indev_get_point(indev, &point);
197	    
198	    switch (code) {
199	        case LV_EVENT_PRESSED:
200	            gesture_start_x = point.x;
201	            gesture_start_y = point.y;
202	            gesture_in_progress = true;
203	            break;
204	        case LV_EVENT_RELEASED:
205	            if (gesture_in_progress) {
206	                int delta_x = point.x - gesture_start_x;
207	                int delta_y = point.y - gesture_start_y;
208	                
209	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
210	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
211	                    // 修改：右滑隐藏秒表界面
212	                    exit_stopwatch();
213	                }
214	                
215	                gesture_in_progress = false;
216	            }
217	            break;
218	        default:
219	            break;
220	    }
221	}
