54	static void update_stopwatch_time(void)
55	{
56	    uint32_t current_time;
57	    uint32_t total_elapsed;
58	    char time_str[16];
59	    
60	    if (stopwatch_running) {
61	        current_time = lv_tick_get();
62	        total_elapsed = stopwatch_elapsed_time + (current_time - stopwatch_start_time);
63	    } else {
64	        total_elapsed = stopwatch_elapsed_time;
65	    }
66	
67	    uint32_t minutes = total_elapsed / 60000;
68	    uint32_t seconds = (total_elapsed % 60000) / 1000;
69	    uint32_t milliseconds = total_elapsed % 1000;
70	    
71	    snprintf(time_str, sizeof(time_str), "%02lu:%02lu.%03lu", minutes, seconds, milliseconds);
72	    lv_label_set_text(stopwatch_label, time_str);
73	}
