137	void timer_gesture_event_cb(lv_event_t *e)
138	{
139	
140	    lv_event_code_t code = lv_event_get_code(e);
141	
142	    switch (code)
143	    {
144	    case LV_EVENT_GESTURE:
145	        lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
146	        if (dir == LV_DIR_BOTTOM)
147	        {
148	            LV_LOG_USER(" LOG_DIR_BOTTOM---But do nothing\n");
149	        }
150	        if (dir == LV_DIR_TOP)
151	        {
152	            LV_LOG_USER(" LV_DIR_TOP---But do nothing\n");
153	        }
154	        if (dir == LV_DIR_LEFT)
155	        {
156	            LV_LOG_USER(" LV_DIR_LEFT---But do nothing\n");
157	        }
158	        if (dir == LV_DIR_RIGHT)
159	        {
160	            if (timerCenterObj && timerCenterObj->menu)
161	            {
162	                lv_obj_t *cur_page = lv_menu_get_cur_main_page(timerCenterObj->menu);
163	                if (cur_page == timerCenterObj->select_page)
164	                {
165	                    lv_menu_set_page(timerCenterObj->menu, timerCenterObj->main_page);
166	                    LV_LOG_USER("Gesture RIGHT: 从select_page返回main_page\n");
167	                }
168	                else if (cur_page == timerCenterObj->run_page)
169	                {
170	                    lv_menu_set_page(timerCenterObj->menu, timerCenterObj->select_page);
171	                    LV_LOG_USER("Gesture RIGHT: 从run_page返回select_page\n");
172	
173	                    run_reset();
174	                }
175	                else if (cur_page == timerCenterObj->main_page)
176	                {
177	                    LV_LOG_USER("appsPage create sucessfully in TimerGesture event !!!!\n");
178	
179	                    /* 删除 timer 容器（menu 是其子对象，会一起被删除）。
180	                     * 容器本身的手势回调也会随对象删除而清理。 */
181	                    lv_obj_t *timer_container = lv_event_get_current_target(e);
182	                    if (timer_container)
183	                    {
184	                        lv_obj_delete(timer_container);
185	                    }
186	
187	                    free(timerCenterObj);
188	                    free(timerControlObj);
189	                    //avoid wild pointer
190	                    timerCenterObj=NULL;
191	                    timerControlObj=NULL;
192	
193	                    LV_LOG_USER("- LV_DIR_RIGHT from Timer home_page current_page is %s!!!!\n", mpd->current_page);
194	
195	                    // 重建 app list（与秒表退出逻辑一致）
196	                    nav_return_from_app();
197	                }
198	            }
199	            break;
200	        default:
201	            break;
202	        }
203	    }
204	}
