970	    /* 添加刻度线 */
971	    const int tick_count = 90;
972	    int center_x = 228;
973	    int center_y = 228;
974	    int outer_radius = 222;
975	    int inner_radius = 200;
976	    for (int i = 0; i < tick_count; i++)
977	    {
978	        double angle_deg = (i * 4.0) - 90.0;
979	        double angle_rad = DEG_TO_RAD(angle_deg); // 使用自定义转换宏
980	
981	        // 创建刻度线
982	        timerControlObj->ticks[i] = lv_line_create(bg_run);
983	
984	        // 设置刻度线样式（默认灰色）
985	        lv_obj_add_style(timerControlObj->ticks[i], &style_line, 0);
986	        // 注: 不再调用 lv_obj_set_style_transform_rotation(angle_rad)。
987	        // LVGL transform_rotation 单位是 0.1 度，传弧度(double→int32 截断为 -1..4)
988	        // 会使每根线进入 LV_LAYER_TYPE_TRANSFORM 软件旋转渲染路径，
989	        // 90 根线 × 455×455 区域单帧绘制爆炸 → 整个表盘卡死。
990	        // 端点已用 cos/sin 表达角度，无需再旋转对象。
991	        // 计算刻度线端点
992	        points[i][0].x = center_x + cos(angle_rad) * outer_radius;
993	        points[i][0].y = center_y + sin(angle_rad) * outer_radius;
994	
995	        int current_inner_radius = inner_radius;
996	        points[i][1].x = center_x + cos(angle_rad) * current_inner_radius;
997	        points[i][1].y = center_y + sin(angle_rad) * current_inner_radius;
998	
999	        lv_line_set_points(timerControlObj->ticks[i], points[i], 2);
1000	    }
