307	            lv_obj_t *child = lv_obj_get_child(parent, i);
308	            if (!child)
309	            {
310	                continue;
311	            }
312	            else if (child == obj)
313	            {
314	                continue;
315	            }
316	            else if (i % 2 == 0)
317	            {
318	                lv_obj_set_style_text_color(child, lv_color_white(), 0);
319	                lv_obj_set_style_text_color(child, lv_color_white(), LV_PART_SELECTED);
320	            }
