static void time_clu_btns_event2(lv_event_t *e)
{
    if (lv_event_get_code(e) == LV_EVENT_CLICKED)
    {
        const char *time_str = (const char *)lv_event_get_user_data(e);
        if (!time_str) return;
        int a = 0, b = 0;
        if (sscanf(time_str, "%d:%d", &a, &b) == 2)
        {
            int ms = (a * 60 + b) * 1000;
            LV_LOG_USER("preset btn2 clicked: %s -> %d ms", time_str, ms);
            timer_start_countdown(ms);
        }
    }
}

