122	    lv_obj_set_style_pad_all(ui_tiles[idx], 0, 0);
123	    lv_obj_clear_flag(ui_tiles[idx], LV_OBJ_FLAG_SCROLLABLE);
124	
125	    /* --- 图标容器（彩色圆角方块）--- */
126	    ui_icon_wraps[idx] = lv_obj_create(ui_tiles[idx]);
