132	    lv_obj_set_style_bg_color(ui_icon_wraps[idx], lv_color_hex(apps[idx].icon_bg), 0);
133	    lv_obj_set_style_bg_opa(ui_icon_wraps[idx], 46, 0);  /* ~18% opacity */
134	    lv_obj_set_style_border_width(ui_icon_wraps[idx], 0, 0);
135	    lv_obj_set_style_pad_all(ui_icon_wraps[idx], 0, 0);
136	    lv_obj_clear_flag(ui_icon_wraps[idx], LV_OBJ_FLAG_SCROLLABLE);
137	    lv_obj_clear_flag(ui_icon_wraps[idx], LV_OBJ_FLAG_CLICKABLE);
138	
139	    /* --- 图标（LVGL symbol 占位）--- */
140	    ui_icon_labels[idx] = lv_label_create(ui_icon_wraps[idx]);
141	    lv_label_set_text(ui_icon_labels[idx], apps[idx].icon);
142	    lv_obj_set_style_text_font(ui_icon_labels[idx], &lv_font_montserrat_24, 0);
143	    lv_obj_set_style_text_color(ui_icon_labels[idx], lv_color_hex(apps[idx].icon_color), 0);
