#ifndef SLEEP_H
#define SLEEP_H

#include <lvgl/lvgl.h>

/* 启动睡眠应用 UI（在当前 watch_scr 上创建） */
void sleep_start(void);

#endif /* SLEEP_H */

/*********************
 *      INCLUDES
 *********************/
#include <lvgl/lvgl.h>
#include <stdio.h>
#include <string.h>
#include "../../sleep/include/sleep.h"
#include "../../utils/include/circle_screen.h"
#include "../../utils/include/font_manager.h"
#include "../../main_page/include/watch_start.h"

/*********************
 *      DEFINES
 *********************/
#define SCR_W   LV_CIRCLE_WATCH   /* 455 */
#define SCR_H   LV_CIRCLE_WATCH

/* 配色 */
#define BG_BASE         lv_color_hex(0x06070D)
#define BG_CARD         lv_color_hex(0x131520)
#define TEXT_PRIMARY    lv_color_hex(0xF8F9FF)
#define TEXT_SECONDARY  lv_color_hex(0xA6ACCD)
#define TEXT_MUTED      lv_color_hex(0x5A5F80)
#define STROKE_SOFT     lv_color_hex(0x1F2133)

/* 睡眠阶段色 */
#define COLOR_DEEP      lv_color_hex(0x6C5CE7)
#define COLOR_LIGHT     lv_color_hex(0xA29BFE)
#define COLOR_REM       lv_color_hex(0x00CEC9)
#define COLOR_AWAKE     lv_color_hex(0xFFD32A)
#define BRAND_PRIMARY   lv_color_hex(0x6C5CE7)

/**********************
 *      TYPEDEFS
 **********************/
/* 静态睡眠数据（演示用） */
typedef struct {
    const char *duration;     /* 总时长 */
    const char *sub_text;     /* 副标题 */
    int deep_pct;             /* 深睡占比 % */
    int light_pct;
    int rem_pct;
    int awake_pct;
    const char *deep_time;
    const char *light_time;
    const char *rem_time;
    const char *awake_time;
    const char *sleep_time;   /* 入睡时间 */
    const char *wake_time;    /* 醒来时间 */
    int score;                /* 睡眠评分 */
} sleep_data_t;

static const sleep_data_t s_data = {
    .duration   = "7:32",
    .sub_text   = "昨晚睡眠时长",
    .deep_pct   = 23,
    .light_pct  = 42,
    .rem_pct    = 27,
    .awake_pct  = 8,
    .deep_time  = "1:44",
    .light_time = "3:10",
    .rem_time   = "2:02",
    .awake_time = "0:36",
    .sleep_time = "23:48",
    .wake_time  = "07:20",
    .score      = 86,
};

/**********************
 *  STATIC VARIABLES
 **********************/
static lv_obj_t *s_container = NULL;

/**********************
 *  STATIC PROTOTYPES
 **********************/
static void gesture_cb(lv_event_t *e);

/**********************
 *   STATIC FUNCTIONS
 **********************/

/* 手势回调：右滑退出 */
static void gesture_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_GESTURE) return;
    lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
    if (dir != LV_DIR_RIGHT) return;

    LV_LOG_USER("sleep: gesture RIGHT -> exit");
    if (s_container) {
        lv_obj_delete(s_container);
        s_container = NULL;
    }
    nav_return_from_app();
}

/* 创建一行图例行（色块 + 名称 + 时间） */
static lv_obj_t *create_legend_row(lv_obj_t *parent, lv_color_t color,
                                    const char *name, const char *time)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_set_size(row, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(row, 0, 0);
    lv_obj_set_style_pad_all(row, 0, 0);
    lv_obj_set_style_pad_column(row, 8, 0);
    lv_obj_set_layout(row, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    /* 色块 */
    lv_obj_t *sw = lv_obj_create(row);
    lv_obj_set_size(sw, 10, 10);
    lv_obj_set_style_radius(sw, 3, 0);
    lv_obj_set_style_bg_color(sw, color, 0);
    lv_obj_set_style_bg_opa(sw, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(sw, 0, 0);
    lv_obj_clear_flag(sw, LV_OBJ_FLAG_SCROLLABLE);

    /* 名称 */
    lv_obj_t *lbl = lv_label_create(row);
    lv_label_set_text(lbl, name);
    lv_obj_set_style_text_font(lbl, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(lbl, TEXT_SECONDARY, 0);

    /* 时间 */
    lv_obj_t *val = lv_label_create(row);
    lv_label_set_text(val, time);
    lv_obj_set_style_text_font(val, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(val, TEXT_PRIMARY, 0);

    return row;
}

/* 创建时间线行 */
static lv_obj_t *create_timeline_row(lv_obj_t *parent, const char *icon,
                                      lv_color_t icon_color,
                                      const char *label, const char *time)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_set_size(row, 310, LV_SIZE_CONTENT);
    lv_obj_set_style_radius(row, 12, 0);
    lv_obj_set_style_bg_color(row, BG_CARD, 0);
    lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(row, 1, 0);
    lv_obj_set_style_border_color(row, STROKE_SOFT, 0);
    lv_obj_set_style_pad_all(row, 12, 0);
    lv_obj_set_style_pad_column(row, 8, 0);
    lv_obj_set_layout(row, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    /* 左侧：图标 + 文字 */
    lv_obj_t *left = lv_obj_create(row);
    lv_obj_set_size(left, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(left, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(left, 0, 0);
    lv_obj_set_style_pad_all(left, 0, 0);
    lv_obj_set_style_pad_column(left, 8, 0);
    lv_obj_set_layout(left, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(left, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(left, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(left, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *ic = lv_label_create(left);
    lv_label_set_text(ic, icon);
    lv_obj_set_style_text_color(ic, icon_color, 0);
    lv_obj_set_style_text_font(ic, &lv_font_montserrat_20, 0);

    lv_obj_t *lbl = lv_label_create(left);
    lv_label_set_text(lbl, label);
    lv_obj_set_style_text_font(lbl, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(lbl, TEXT_SECONDARY, 0);

    /* 右侧：时间 */
    lv_obj_t *t = lv_label_create(row);
    lv_label_set_text(t, time);
    lv_obj_set_style_text_font(t, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(t, TEXT_PRIMARY, 0);

    return row;
}

/**********************
 *   GLOBAL FUNCTIONS
 **********************/
void sleep_start(void)
{
    LV_LOG_USER("sleep_start ENTER");

    lv_obj_t *scr = get_watch_scr();
    if (!scr) return;

    /* 根容器 */
    s_container = lv_obj_create(scr);
    lv_obj_set_size(s_container, SCR_W, SCR_H);
    lv_obj_align(s_container, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(s_container, BG_BASE, 0);
    lv_obj_set_style_bg_opa(s_container, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(s_container, 0, 0);
    lv_obj_set_style_pad_all(s_container, 0, 0);
    lv_obj_set_scrollbar_mode(s_container, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(s_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_radius(s_container, LV_RADIUS_CIRCLE, 0);

    /* 手势 */
    lv_obj_add_event_cb(s_container, gesture_cb, LV_EVENT_GESTURE, NULL);
    lv_obj_remove_flag(s_container, LV_OBJ_FLAG_GESTURE_BUBBLE);

    /* ---- 内容容器（垂直 Flex 居中）---- */
    lv_obj_t *content = lv_obj_create(s_container);
    lv_obj_set_size(content, SCR_W, SCR_H);
    lv_obj_align(content, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_style_pad_all(content, 0, 0);
    lv_obj_set_layout(content, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(content, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(content, 0, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLLABLE);

    /* ============ 标题区域 ============ */
    lv_obj_t *head = lv_obj_create(content);
    lv_obj_set_size(head, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(head, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(head, 0, 0);
    lv_obj_set_style_pad_all(head, 0, 0);
    lv_obj_set_style_pad_column(head, 10, 0);
    lv_obj_set_layout(head, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(head, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(head, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(head, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(head, 50, 0);

    /* 月亮图标 */
    lv_obj_t *moon_ic = lv_label_create(head);
    lv_label_set_text(moon_ic, LV_SYMBOL_IMAGE);
    lv_obj_set_style_text_color(moon_ic, BRAND_PRIMARY, 0);
    lv_obj_set_style_text_font(moon_ic, &lv_font_montserrat_22, 0);

    /* "睡眠" 标题 */
    lv_obj_t *title = lv_label_create(head);
    lv_label_set_text(title, "睡眠");
    lv_obj_set_style_text_font(title, font_manager_get_font(FONT_MEDIUM), 0);
    lv_obj_set_style_text_color(title, TEXT_PRIMARY, 0);

    /* ============ 时长数字 ============ */
    lv_obj_t *dur_num = lv_label_create(content);
    lv_label_set_text(dur_num, s_data.duration);
    lv_obj_set_style_text_font(dur_num, &lv_font_montserrat_48, 0);
    lv_obj_set_style_text_color(dur_num, TEXT_PRIMARY, 0);
    lv_obj_set_style_pad_top(dur_num, 10, 0);

    /* 副标题 */
    lv_obj_t *dur_sub = lv_label_create(content);
    lv_label_set_text(dur_sub, s_data.sub_text);
    lv_obj_set_style_text_font(dur_sub, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(dur_sub, TEXT_SECONDARY, 0);
    lv_obj_set_style_pad_top(dur_sub, 4, 0);

    /* ============ 阶段条 ============ */
    lv_obj_t *stages = lv_obj_create(content);
    lv_obj_set_size(stages, 310, 18);
    lv_obj_set_style_radius(stages, 9, 0);
    lv_obj_set_style_border_width(stages, 1, 0);
    lv_obj_set_style_border_color(stages, STROKE_SOFT, 0);
    lv_obj_set_style_bg_opa(stages, LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(stages, 0, 0);
    lv_obj_set_layout(stages, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(stages, LV_FLEX_FLOW_ROW);
    lv_obj_clear_flag(stages, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(stages, 18, 0);
    lv_obj_set_style_clip_corner(stages, true, 0);

    /* 各阶段色块 */
    struct { int pct; lv_color_t color; } stage_parts[] = {
        { s_data.deep_pct,  COLOR_DEEP  },
        { s_data.light_pct, COLOR_LIGHT },
        { s_data.rem_pct,   COLOR_REM   },
        { s_data.awake_pct, COLOR_AWAKE },
    };
    for (int i = 0; i < 4; i++) {
        lv_obj_t *bar = lv_obj_create(stages);
        int w = 310 * stage_parts[i].pct / 100;
        lv_obj_set_size(bar, w, 18);
        lv_obj_set_style_bg_color(bar, stage_parts[i].color, 0);
        lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
        lv_obj_set_style_border_width(bar, 0, 0);
        lv_obj_set_style_radius(bar, 0, 0);
        lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
    }

    /* ============ 图例（2×2 网格） ============ */
    lv_obj_t *legend = lv_obj_create(content);
    lv_obj_set_size(legend, 310, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(legend, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(legend, 0, 0);
    lv_obj_set_style_pad_all(legend, 0, 0);
    lv_obj_set_layout(legend, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(legend, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_flex_align(legend, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_row(legend, 8, 0);
    lv_obj_clear_flag(legend, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(legend, 12, 0);

    create_legend_row(legend, COLOR_DEEP,  "深睡",     s_data.deep_time);
    create_legend_row(legend, COLOR_LIGHT, "浅睡",     s_data.light_time);
    create_legend_row(legend, COLOR_REM,   "快速眼动", s_data.rem_time);
    create_legend_row(legend, COLOR_AWAKE, "清醒",     s_data.awake_time);

    /* ============ 时间线 ============ */
    lv_obj_t *timeline = lv_obj_create(content);
    lv_obj_set_size(timeline, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(timeline, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(timeline, 0, 0);
    lv_obj_set_style_pad_all(timeline, 0, 0);
    lv_obj_set_style_pad_row(timeline, 10, 0);
    lv_obj_set_layout(timeline, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(timeline, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(timeline, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(timeline, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(timeline, 16, 0);

    create_timeline_row(timeline, LV_SYMBOL_IMAGE,
                        COLOR_DEEP, "入睡", s_data.sleep_time);
    create_timeline_row(timeline, LV_SYMBOL_EYE_OPEN,
                        COLOR_AWAKE, "醒来", s_data.wake_time);

    /* ============ 睡眠评分 ============ */
    lv_obj_t *score_row = lv_obj_create(content);
    lv_obj_set_size(score_row, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(score_row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(score_row, 0, 0);
    lv_obj_set_style_pad_all(score_row, 0, 0);
    lv_obj_set_style_pad_column(score_row, 8, 0);
    lv_obj_set_layout(score_row, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(score_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(score_row, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(score_row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(score_row, 16, 0);

    lv_obj_t *score_lbl = lv_label_create(score_row);
    lv_label_set_text(score_lbl, "睡眠评分");
    lv_obj_set_style_text_font(score_lbl, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(score_lbl, TEXT_SECONDARY, 0);

    lv_obj_t *score_val = lv_label_create(score_row);
    lv_label_set_text_fmt(score_val, "%d", s_data.score);
    lv_obj_set_style_text_font(score_val, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(score_val, BRAND_PRIMARY, 0);

    LV_LOG_USER("sleep_start DONE");
}

#ifndef HEART_H
#define HEART_H

#include <lvgl/lvgl.h>

/* 启动心率应用 UI（在当前 watch_scr 上创建） */
void heart_start(void);

#endif /* HEART_H */

/*********************
 *      INCLUDES
 *********************/
#include <lvgl/lvgl.h>
#include <stdio.h>
#include <string.h>
#include "../../heart/include/heart.h"
#include "../../utils/include/circle_screen.h"
#include "../../utils/include/font_manager.h"
#include "../../main_page/include/watch_start.h"

/*********************
 *      DEFINES
 *********************/
#define SCR_W   LV_CIRCLE_WATCH   /* 455 */
#define SCR_H   LV_CIRCLE_WATCH

/* 配色 */
#define BG_BASE         lv_color_hex(0x06070D)
#define BG_CARD         lv_color_hex(0x131520)
#define TEXT_PRIMARY    lv_color_hex(0xF8F9FF)
#define TEXT_SECONDARY  lv_color_hex(0xA6ACCD)
#define TEXT_MUTED      lv_color_hex(0x5A5F80)
#define STROKE_SOFT     lv_color_hex(0x1F2133)
#define BRAND_RED       lv_color_hex(0xFF6B6B)

/* 心率区间色 */
#define HR_ZONE1_COLOR  lv_color_hex(0x5A5F80)   /* 热身 */
#define HR_ZONE2_COLOR  lv_color_hex(0x00CEC9)   /* 燃脂 */
#define HR_ZONE3_COLOR  lv_color_hex(0xFFA502)   /* 有氧 */
#define HR_ZONE4_COLOR  lv_color_hex(0xFF6B6B)   /* 无氧 */
#define HR_ZONE5_COLOR  lv_color_hex(0xEF4444)   /* 极限 */

/**********************
 *      TYPEDEFS
 **********************/
/* 静态心率数据（演示用） */
typedef struct {
    int current_hr;       /* 当前心率 */
    int resting_hr;       /* 静息心率 */
    int max_hr;           /* 最大心率 */
    int min_hr;           /* 最小心率 */
    const char *zone_name;/* 当前区间名 */
    int zone_pct;         /* 当前区间占比 % */
    const char *measure_time; /* 测量时间 */
    /* 5个区间占比 */
    int zones[5];
} heart_data_t;

static const heart_data_t s_data = {
    .current_hr   = 72,
    .resting_hr   = 62,
    .max_hr       = 98,
    .min_hr       = 58,
    .zone_name    = "燃脂",
    .zone_pct     = 45,
    .measure_time = "09:35",
    .zones        = { 15, 45, 25, 10, 5 },  /* 热身/燃脂/有氧/无氧/极限 */
};

/**********************
 *  STATIC VARIABLES
 **********************/
static lv_obj_t *s_container = NULL;

/**********************
 *  STATIC PROTOTYPES
 **********************/
static void gesture_cb(lv_event_t *e);

/**********************
 *   STATIC FUNCTIONS
 **********************/

/* 手势回调：右滑退出 */
static void gesture_cb(lv_event_t *e)
{
    if (lv_event_get_code(e) != LV_EVENT_GESTURE) return;
    lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_active());
    if (dir != LV_DIR_RIGHT) return;

    LV_LOG_USER("heart: gesture RIGHT -> exit");
    if (s_container) {
        lv_obj_delete(s_container);
        s_container = NULL;
    }
    nav_return_from_app();
}

/* 创建一个指标卡片行 */
static lv_obj_t *create_metric_row(lv_obj_t *parent, const char *label,
                                    const char *value, lv_color_t val_color)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_set_size(row, 310, LV_SIZE_CONTENT);
    lv_obj_set_style_radius(row, 12, 0);
    lv_obj_set_style_bg_color(row, BG_CARD, 0);
    lv_obj_set_style_bg_opa(row, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(row, 1, 0);
    lv_obj_set_style_border_color(row, STROKE_SOFT, 0);
    lv_obj_set_style_pad_all(row, 14, 0);
    lv_obj_set_layout(row, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *lbl = lv_label_create(row);
    lv_label_set_text(lbl, label);
    lv_obj_set_style_text_font(lbl, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(lbl, TEXT_SECONDARY, 0);

    lv_obj_t *val = lv_label_create(row);
    lv_label_set_text(val, value);
    lv_obj_set_style_text_font(val, &lv_font_montserrat_20, 0);
    lv_obj_set_style_text_color(val, val_color, 0);

    return row;
}

/**********************
 *   GLOBAL FUNCTIONS
 **********************/
void heart_start(void)
{
    LV_LOG_USER("heart_start ENTER");

    lv_obj_t *scr = get_watch_scr();
    if (!scr) return;

    /* 根容器 */
    s_container = lv_obj_create(scr);
    lv_obj_set_size(s_container, SCR_W, SCR_H);
    lv_obj_align(s_container, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_color(s_container, BG_BASE, 0);
    lv_obj_set_style_bg_opa(s_container, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(s_container, 0, 0);
    lv_obj_set_style_pad_all(s_container, 0, 0);
    lv_obj_set_scrollbar_mode(s_container, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(s_container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_radius(s_container, LV_RADIUS_CIRCLE, 0);

    /* 手势 */
    lv_obj_add_event_cb(s_container, gesture_cb, LV_EVENT_GESTURE, NULL);
    lv_obj_remove_flag(s_container, LV_OBJ_FLAG_GESTURE_BUBBLE);

    /* ---- 内容容器（垂直 Flex 居中）---- */
    lv_obj_t *content = lv_obj_create(s_container);
    lv_obj_set_size(content, SCR_W, SCR_H);
    lv_obj_align(content, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(content, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(content, 0, 0);
    lv_obj_set_style_pad_all(content, 0, 0);
    lv_obj_set_layout(content, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(content, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(content, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(content, 0, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLLABLE);

    /* ============ 标题区域 ============ */
    lv_obj_t *head = lv_obj_create(content);
    lv_obj_set_size(head, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(head, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(head, 0, 0);
    lv_obj_set_style_pad_all(head, 0, 0);
    lv_obj_set_style_pad_column(head, 10, 0);
    lv_obj_set_layout(head, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(head, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(head, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(head, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(head, 50, 0);

    /* 心率图标 */
    lv_obj_t *heart_ic = lv_label_create(head);
    lv_label_set_text(heart_ic, LV_SYMBOL_HEART);
    lv_obj_set_style_text_color(heart_ic, BRAND_RED, 0);
    lv_obj_set_style_text_font(heart_ic, &lv_font_montserrat_22, 0);

    /* "心率" 标题 */
    lv_obj_t *title = lv_label_create(head);
    lv_label_set_text(title, "心率");
    lv_obj_set_style_text_font(title, font_manager_get_font(FONT_MEDIUM), 0);
    lv_obj_set_style_text_color(title, TEXT_PRIMARY, 0);

    /* ============ 心率大数字 ============ */
    lv_obj_t *hr_num = lv_label_create(content);
    lv_label_set_text_fmt(hr_num, "%d", s_data.current_hr);
    lv_obj_set_style_text_font(hr_num, &lv_font_montserrat_48, 0);
    lv_obj_set_style_text_color(hr_num, BRAND_RED, 0);
    lv_obj_set_style_pad_top(hr_num, 10, 0);

    /* bpm 单位 */
    lv_obj_t *hr_unit = lv_label_create(content);
    lv_label_set_text(hr_unit, "bpm");
    lv_obj_set_style_text_font(hr_unit, font_manager_get_font(FONT_SMALL), 0);
    lv_obj_set_style_text_color(hr_unit, TEXT_SECONDARY, 0);
    lv_obj_set_style_pad_top(hr_unit, 2, 0);

    /* ============ 心率区间条 ============ */
    lv_obj_t *zone_bar = lv_obj_create(content);
    lv_obj_set_size(zone_bar, 310, 18);
    lv_obj_set_style_radius(zone_bar, 9, 0);
    lv_obj_set_style_border_width(zone_bar, 1, 0);
    lv_obj_set_style_border_color(zone_bar, STROKE_SOFT, 0);
    lv_obj_set_style_bg_opa(zone_bar, LV_OPA_TRANSP, 0);
    lv_obj_set_style_pad_all(zone_bar, 0, 0);
    lv_obj_set_layout(zone_bar, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(zone_bar, LV_FLEX_FLOW_ROW);
    lv_obj_clear_flag(zone_bar, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(zone_bar, 18, 0);
    lv_obj_set_style_clip_corner(zone_bar, true, 0);

    lv_color_t zone_colors[] = {
        HR_ZONE1_COLOR, HR_ZONE2_COLOR, HR_ZONE3_COLOR,
        HR_ZONE4_COLOR, HR_ZONE5_COLOR
    };
    for (int i = 0; i < 5; i++) {
        if (s_data.zones[i] <= 0) continue;
        lv_obj_t *bar = lv_obj_create(zone_bar);
        int w = 310 * s_data.zones[i] / 100;
        if (w < 2) w = 2;
        lv_obj_set_size(bar, w, 18);
        lv_obj_set_style_bg_color(bar, zone_colors[i], 0);
        lv_obj_set_style_bg_opa(bar, LV_OPA_COVER, 0);
        lv_obj_set_style_border_width(bar, 0, 0);
        lv_obj_set_style_radius(bar, 0, 0);
        lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);
    }

    /* ============ 区间名称 ============ */
    lv_obj_t *zone_label = lv_obj_create(content);
    lv_obj_set_size(zone_label, 310, LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(zone_label, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(zone_label, 0, 0);
    lv_obj_set_style_pad_all(zone_label, 0, 0);
    lv_obj_set_layout(zone_label, LV_LAYOUT_FLEX);
    lv_obj_set_flex_flow(zone_label, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(zone_label, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_clear_flag(zone_label, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(zone_label, 8, 0);

    const char *zone_names[] = {"热身", "燃脂", "有氧", "无氧", "极限"};
    const char *zone_range[] = {"<114", "114-133", "133-152", "152-171", ">171"};

    for (int i = 0; i < 5; i++) {
        lv_obj_t *z = lv_obj_create(zone_label);
        lv_obj_set_size(z, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
        lv_obj_set_style_bg_opa(z, LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(z, 0, 0);
        lv_obj_set_style_pad_all(z, 0, 0);
        lv_obj_set_style_pad_column(z, 2, 0);
        lv_obj_set_layout(z, LV_LAYOUT_FLEX);
        lv_obj_set_flex_flow(z, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_flex_align(z, LV_FLEX_ALIGN_CENTER,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_clear_flag(z, LV_OBJ_FLAG_SCROLLABLE);

        /* 区间名 */
        bool is_active = (strcmp(s_data.zone_name, zone_names[i]) == 0);
        lv_obj_t *name_lbl = lv_label_create(z);
        lv_label_set_text(name_lbl, zone_names[i]);
        lv_obj_set_style_text_font(name_lbl, font_manager_get_font(FONT_SMALL), 0);
        lv_obj_set_style_text_color(name_lbl,
                                    is_active ? TEXT_PRIMARY : TEXT_MUTED, 0);

        /* bpm 范围 */
        lv_obj_t *range_lbl = lv_label_create(z);
        lv_label_set_text(range_lbl, zone_range[i]);
        lv_obj_set_style_text_font(range_lbl, &lv_font_montserrat_14, 0);
        lv_obj_set_style_text_color(range_lbl, TEXT_MUTED, 0);
    }

    /* ============ 静息心率 ============ */
    char rhr_str[16];
    snprintf(rhr_str, sizeof(rhr_str), "%d bpm", s_data.resting_hr);
    create_metric_row(content, "静息心率", rhr_str, TEXT_PRIMARY);

    /* ============ 测量时间 ============ */
    create_metric_row(content, "最近测量", s_data.measure_time, BRAND_RED);

    LV_LOG_USER("heart_start DONE");
}

