7	<link rel="stylesheet" href="css/watch.css">
8	<style>
9	  .run-bg {
10	    position:absolute; inset:0;
11	    background:
12	      radial-gradient(circle at 50% 38%, rgba(38,222,129,0.12), transparent 58%),
13	      var(--bg-base);
14	  }
15	  .head { margin-top:50px; display:flex; align-items:center; justify-content:center; gap:10px; }
16	  .head .ic { width:22px; height:22px; color: var(--brand-success); }
17	  .head h1 { font-size:18px; font-weight:600; }
18	
19	  /* ===== 状态视图（绝对定位叠加，通过 opacity 切换） ===== */
20	  .stage {
21	    position:absolute; inset:0;
22	    display:flex; flex-direction:column; align-items:center;
23	    opacity:0; pointer-events:none;
24	    transition: opacity .4s var(--ease-out);
25	  }
26	  .stage.active { opacity:1; pointer-events:auto; }
27	
28	  .hint { font-size:14px; color:var(--text-secondary); }
29	
30	  /* ---- Stage: Ready 准备开始 ---- */
31	  #ready { padding-top:130px; gap:26px; }
32	  .ready-tip { font-size:22px; font-weight:600; }
33	  .goal-chip {
34	    display:flex; align-items:center; gap:8px;
35	    font-size:13px; color:var(--text-secondary);
36	    padding:8px 16px; border-radius:var(--r-pill);
37	    background:var(--bg-card); border:1px solid var(--stroke-faint);
38	  }
