43	    background: linear-gradient(145deg, var(--brand-success), #15b864);
44	    color:#fff; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px;
45	    box-shadow: var(--glow-success), inset 0 2px 6px rgba(255,255,255,0.25), inset 0 -6px 12px rgba(0,0,0,0.3);
46	    transition: transform var(--dur-fast) var(--ease-spring);
47	    animation: breathe 2.6s ease-in-out infinite;
48	  }
49	  .start-btn:active { transform: scale(0.93); }
50	  .start-btn svg { width:44px; height:44px; }
51	  .start-btn span { font-size:13px; font-weight:600; letter-spacing:2px; }
52	
53	  .stats-row { display:flex; gap:36px; margin-top:6px; }
54	  .stat-mini { text-align:center; }
55	  .stat-mini .v { font-family:var(--font-num); font-size:17px; font-weight:700; color:var(--text-primary); }
56	  .stat-mini .u { font-size:11px; color:var(--text-muted); }
57	
58	  /* ---- Stage: Countdown 3-2-1 ---- */
59	  #countdown { justify-content:center; }
60	  .cd-ring { position:relative; width:280px; height:280px; display:flex; align-items:center; justify-content:center; }
61	  .cd-ring svg { position:absolute; }
62	  .cd-num {
63	    font-family:var(--font-num); font-size:130px; font-weight:700; line-height:1;
64	    color:#fff; text-shadow:0 0 50px rgba(38,222,129,0.55);
65	  }
